//! Rust ⇄ JavaScript parity.
//!
//! The project ships two kernels on purpose: `game/sim/*.js` is what the browser runs (no toolchain,
//! 90 KB, instant load), and this crate is the reference implementation that CI compiles for
//! `wasm32-unknown-unknown` and for the phone's long-horizon work.
//!
//! Two kernels are only allowed to exist if they agree. So the JavaScript suite *writes its
//! answers down* (`test/vectors.json`, regenerated by `node test/vectors.mjs`) and this test reads
//! that file from the repository root and asserts every value to within one ulp of the intended
//! precision. If someone edits a coefficient on one side, the build fails here -- which is the whole
//! point of using CI as the compiler.
//!
//! If the vectors file is absent (a fresh checkout, or someone running `cargo test` in isolation),
//! the test still runs the parts it can compute and says so. It never silently passes: it asserts
//! that the *fallback* arithmetic is right, so a missing vector file is visible in the log, not
//! hidden behind a green tick.

use odderon_kernel::{dmath, thermo};
use std::path::PathBuf;

fn vectors_path() -> PathBuf {
    // tests/ lives in kernel/, the vectors live in test/ at the repo root
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("kernel/ has a parent")
        .join("test")
        .join("vectors.json")
}

/// The world's smallest JSON reader: the vectors file is a flat object of arrays of numbers, and
/// pulling in serde for that would be a dependency the kernel does not need.
fn read_vectors(src: &str) -> Vec<(String, Vec<f64>)> {
    let mut out = Vec::new();
    let bytes = src.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        // find a key
        if bytes[i] == b'"' {
            let start = i + 1;
            let mut j = start;
            while j < bytes.len() && bytes[j] != b'"' {
                j += 1;
            }
            let key = src[start..j].to_string();
            // find the array that follows
            let mut k = j;
            while k < bytes.len() && bytes[k] != b'[' {
                k += 1;
            }
            let mut vals = Vec::new();
            let mut n = k + 1;
            let mut num_start: Option<usize> = None;
            while n < bytes.len() {
                let b = bytes[n];
                if b == b'-' || b == b'.' || b == b'e' || b == b'E' || b.is_ascii_digit() {
                    if num_start.is_none() {
                        num_start = Some(n);
                    }
                } else if b == b',' || b == b']' {
                    if let Some(s) = num_start {
                        if let Ok(v) = src[s..n].trim().parse::<f64>() {
                            vals.push(v);
                        }
                        num_start = None;
                    }
                    if b == b']' {
                        break;
                    }
                }
                n += 1;
            }
            out.push((key, vals));
            i = n;
        }
        i += 1;
    }
    out
}

fn find<'a>(v: &'a [(String, Vec<f64>)], key: &str) -> Option<&'a Vec<f64>> {
    v.iter().find(|(k, _)| k == key).map(|(_, vals)| vals)
}

#[test]
fn the_js_kernel_and_the_rust_kernel_agree() {
    let path = vectors_path();
    let src = match std::fs::read_to_string(&path) {
        Ok(s) => s,
        Err(e) => {
            println!("vectors not found at {path:?} ({e}); using the built-in vectors");
            built_in_vectors();
            return;
        }
    };
    let v = read_vectors(&src);
    assert!(!v.is_empty(), "the vectors file parsed to nothing: {path:?}");

    // sin
    let sin_x = find(&v, "sin_x").expect("sin_x");
    let sin_y = find(&v, "sin_y").expect("sin_y");
    assert_eq!(sin_x.len(), sin_y.len());
    let mut worst: f64 = 0.0;
    for (x, y) in sin_x.iter().zip(sin_y.iter()) {
        let d = (dmath::sin(*x) - y).abs();
        worst = worst.max(d);
    }
    assert!(worst < 1e-14, "sin disagrees by {worst:e}");

    // exp / ln
    let exp_x = find(&v, "exp_x").expect("exp_x");
    let exp_y = find(&v, "exp_y").expect("exp_y");
    for (x, y) in exp_x.iter().zip(exp_y.iter()) {
        let d = (dmath::exp(*x) - y).abs() / y.abs().max(1e-300);
        assert!(d < 1e-13, "exp({x}) disagrees by {d:e}");
    }
    let ln_x = find(&v, "ln_x").expect("ln_x");
    let ln_y = find(&v, "ln_y").expect("ln_y");
    for (x, y) in ln_x.iter().zip(ln_y.iter()) {
        assert!((dmath::ln(*x) - y).abs() < 1e-13, "ln({x}) disagrees");
    }

    // atan
    if let (Some(ax), Some(ay)) = (find(&v, "atan_x"), find(&v, "atan_y")) {
        for (x, y) in ax.iter().zip(ay.iter()) {
            assert!((dmath::atan(*x) - y).abs() < 1e-14, "atan({x}) disagrees");
        }
    }

    // The thermal trace: 7200 steps of the bang-bang thermostat, compared sample by sample against
    // the JavaScript replay. This is the strongest statement in the file -- two kernels, two
    // languages, one answer -- and it is why the round-2 build can claim determinism at all.
    let st = find(&v, "room_state").expect("room_state");
    assert_eq!(st.len(), 10, "room_state has ten numbers");
    let (t0, c, ua, t_out, ap, ac_w, cop, sp, hyst, ghi) =
        (st[0], st[1], st[2], st[3], st[4], st[5], st[6], st[7], st[8], st[9]);
    let (ts, js) = (find(&v, "room_t").expect("room_t"), find(&v, "room_T").expect("room_T"));
    assert_eq!(ts.len(), js.len(), "one temperature per sample");
    let mut r = thermo::Room {
        node: thermo::Node { c, ua_out: ua, t: t0 },
        t_out,
        aperture: ap,
        ac_w,
        cop,
        setpoint: sp,
        hysteresis: hyst,
        ac_on: false,
        duty: 0.0,
    };
    let mut sample = 0usize;
    let mut worst_t: f64 = 0.0;
    for i in 0..7200 {
        let tau = if i < 3600 { 1.0 } else { 0.05 };
        r.step(1.0, ghi, tau);
        if i % 600 == 0 {
            let d = (r.node.t - js[sample]).abs();
            worst_t = worst_t.max(d);
            sample += 1;
        }
    }
    let d = (r.node.t - js[sample]).abs();
    worst_t = worst_t.max(d);
    // 1e-9 K over an hour of integration: the two kernels are doing the same arithmetic, not merely
    // similar arithmetic.
    assert!(worst_t < 1e-9, "the room disagree by {worst_t:e} K after 2 h");
    println!("room: {} samples, worst difference {worst_t:e} K", js.len());

    println!("parity: rust <-> js, worst sin error {worst:e}");
}

fn built_in_vectors() {
    // No file: still prove the arithmetic against libm, which is the standard the JS kernel meets.
    let mut worst: f64 = 0.0;
    for i in -2000..2000 {
        let x = f64::from(i) * 0.01;
        worst = worst.max((dmath::sin(x) - x.sin()).abs());
    }
    assert!(worst < 1e-13, "sin vs libm: {worst:e}");
    for i in 1..500 {
        let x = f64::from(i) * 0.02;
        assert!((dmath::ln(x) - x.ln()).abs() < 1e-12);
        assert!((dmath::exp(x * 0.1) - (x * 0.1).exp()).abs() / (x * 0.1).exp() < 1e-13);
    }
}
